 ## Unreleased

+- Add optional limit and offset pagination to `GET /items`, with status 400 for invalid values.
 - Faster tag lookup.

 ## 1.4.2 - 2026-09-30
diff --git a/README.md b/README.md
index 37fe697..6ca8db6 100644
--- a/README.md
+++ b/README.md
@@ -11,5 +11,5 @@ Current version: 1.4.2.

 ## Routes

-- `GET /items`: every item.
+- `GET /items`: every item, or an array page with optional `?limit=N&offset=M`. `limit` must be a whole number from 1 to 50; `offset` must be a whole number from 0 (default 0). Omitting `limit` returns all remaining items. Invalid pagination returns status 400.
 - `GET /expiring`: items that expire within a week.
diff --git a/src/server.js b/src/server.js
index 988f86d..fdfb033 100644
--- a/src/server.js
+++ b/src/server.js
@@ -8,9 +8,28 @@ const PORT = Number(process.env.PORT || 4300);

 /** Answers one request: { status, body }. */
 export async function handle(path, now = Date.now()) {
+  const { pathname, searchParams } = new URL(path, "http://x");
   const items = await fetchItems();
-  if (path === "/items") return { status: 200, body: items };
-  if (path === "/expiring")
+  if (pathname === "/items") {
+    for (const name of ["limit", "offset"]) {
+      const values = searchParams.getAll(name);
+      if (values.length === 0) continue;
+      const value = Number(values[0]);
+      if (
+        values.length > 1 ||
+        !/^[0-9]+$/.test(values[0]) ||
+        !Number.isInteger(value) ||
+        value < (name === "limit" ? 1 : 0) ||
+        (name === "limit" && value > 50)
+      ) {
+        return httpError(400, "invalid_pagination", "Invalid limit or offset.");
+      }
+    }
+    const offset = Number(searchParams.get("offset") ?? 0);
+    const limit = searchParams.has("limit") ? Number(searchParams.get("limit")) : undefined;
+    return { status: 200, body: items.slice(offset, limit === undefined ? undefined : offset + limit) };
+  }
+  if (pathname === "/expiring")
     return {
       status: 200,
       body: items.filter((i) => !isExpired(i, now) && daysLeft(i, now) <= 7),
@@ -20,7 +39,7 @@ export async function handle(path, now = Date.now()) {

 if (import.meta.url === `file://${process.argv[1]}`) {
